function pvAgg(ds, list) {
  if (PVX[ds]) { const o = {}; PVX[ds].meas.forEach(function (m) { o[m.k] = list.length ? m.f(list) : null; }); return o; }
  if (ds === 'inc') {
    let open = 0, crit = 0, aS = 0, rS = 0, rN = 0;
    list.forEach(function (r) { if (r.Status !== 'Closed') { open++; aS += r.age; } else { rS += r.res; rN++; } if (r.Severity === 'Critical') crit++; });
    return { n: list.length, open: open, closed: list.length - open, crit: crit, age: open ? aS / open : null, res: rN ? rS / rN : null };
  }
  const o = { target: 0, procured: 0, farmers: 0, paid: 0, p24w: 0, cmrDel: 0 };
  list.forEach(function (r) { o.target += r.target; o.procured += r.procured; o.farmers += r.farmers; o.paid += r.paid; o.p24w += r.p24w; o.cmrDel += r.cmrDel; });
  o.pct = o.target ? o.procured / o.target * 100 : null; o.pay24 = o.paid ? Math.min(99, o.p24w / o.paid * 100) : null;
  if (!list.length) { o.target = o.procured = o.farmers = o.paid = o.cmrDel = null; }
  return o;
}
function pvOrder(field, vals) {
  const by = function (arr) { return arr.filter(function (x) { return vals.indexOf(x) >= 0; }); };
  if (field === 'Month') return by(MONTHS12);
  if (field === 'Season') return by(SEASONS_INC);
  if (field === 'Severity') return by(['Critical', 'High', 'Medium', 'Low']);
  if (field === 'Region') return by(REGIONS);
  if (field === 'Status') return by(['Escalated', 'Open', 'In progress', 'Closed']);
  return vals.slice().sort();
}
